<?php
declare(strict_types=1);
namespace App\Repository\Cms; use App\Entity\Cms\CmsMenu; use Doctrine\Bundle\DoctrineBundle\Repository\ServiceEntityRepository; use Doctrine\Persistence\ManagerRegistry; final class CmsMenuRepository extends ServiceEntityRepository{public function __construct(ManagerRegistry $r){parent::__construct($r,CmsMenu::class);} public function findResolved(string $code,object $channel,string $locale):?CmsMenu{return $this->createQueryBuilder('m')->addSelect('i','p','t')->leftJoin('m.items','i','WITH','i.enabled=true AND i.channel=:channel AND i.locale=:locale')->leftJoin('i.page','p')->leftJoin('p.translations','t','WITH','t.locale=:locale')->andWhere('m.code=:code AND m.enabled=true')->setParameters(compact('code','channel','locale'))->orderBy('i.position','ASC')->getQuery()->getOneOrNullResult();}}
